import items from './items.json' with {type:'json'};

export async function listTools() {
  return [{
    name: 'catalog_search',
    description: 'Search the catalog by name (case-insensitive) with pagination.',
    inputSchema: {
      type: 'object',
      properties: {
        query: { type: 'string', description: 'Substring to search for in item names (case-insensitive).' },
        offset: { type: 'integer', minimum: 0, default: 0, description: 'Number of matching rows to skip.' },
        limit: { type: 'integer', minimum: 1, maximum: 5, default: 2, description: 'Maximum number of rows to return (1–5).' }
      },
      required: ['query'],
      additionalProperties: false
    }
  }];
}

export async function callTool(name, args) {
  if (name !== 'catalog_search') {
    throw new Error(`Unknown tool: ${name}`);
  }
  // Validate arguments
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments');
  }
  const allowed = ['query', 'offset', 'limit'];
  for (const key of Object.keys(args)) {
    if (!allowed.includes(key)) {
      throw new Error(`Unknown argument: ${key}`);
    }
  }
  const { query } = args;
  if (typeof query !== 'string') {
    throw new Error('query must be a string');
  }
  let offset = 0;
  if ('offset' in args) {
    offset = args.offset;
    if (!Number.isInteger(offset) || offset < 0) {
      throw new Error('offset must be a non-negative integer');
    }
  }
  let limit = 2;
  if ('limit' in args) {
    limit = args.limit;
    if (!Number.isInteger(limit) || limit < 1 || limit > 5) {
      throw new Error('limit must be an integer between 1 and 5');
    }
  }
  const q = query.toLowerCase();
  const matches = items.filter(it => typeof it.name === 'string' && it.name.toLowerCase().includes(q));
  const total = matches.length;
  const rows = matches.slice(offset, offset + limit);
  const result = { rows, total };
  if (offset + limit < total) {
    result.next_offset = offset + limit;
  }
  return {
    content: [{ type: 'text', text: JSON.stringify(result) }]
  };
}
